.site-header {
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  padding: 0 2rem;
  height: 60px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky;
  top: 0;
  z-index: 100;
}

.site-logo {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--color-text);
  text-decoration: none;
}

.site-logo svg { flex-shrink: 0; }

.breadcrumb {
  display: flex;
  align-items: center;
  gap: .4rem;
  font-size: .875rem;
  color: var(--color-text-muted);
  list-style: none;
}
.breadcrumb a {
  color: var(--color-text-muted);
  text-decoration: none;
