.image-meta-bar {
  padding: 1.5rem 2rem;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1.5rem;
  flex-wrap: wrap;
}

.image-info { flex: 1 1 200px; }

.image-title {
  font-size: 1.2rem;
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: .35rem;
}

.image-details {
  display: flex;
  flex-wrap: wrap;
  gap: .25rem .75rem;
  font-size: .8125rem;
  color: var(--color-text-muted);
}

.detail-chip {
  display: flex;
  align-items: center;
  gap: .3rem;
}

/* ── Action buttons ─────────────────────────────────────────────────── */
.actions {
  display: flex;
  align-items: center;
  gap: .625rem;
  flex-shrink: 0;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: .4rem;
  padding: .55rem 1.1rem;
  border-radius: var(--radius-sm);
  font-size: .875rem;
  font-weight: 600;
  font-family: var(--font);
  cursor: pointer;
  transition: background .15s, box-shadow .15s, color .15s;
  border: 1.5px solid transparent;
  text-decoration: none;
  white-space: nowrap;
}

.btn-ghost {
  background: transparent;
  border-color: var(--color-border);
  color: var(--color-text);
}
.btn-ghost:hover { background: var(--color-surface-2); }

.btn-primary {
  background: var(--color-accent);
  color: #fff;
  border-color: var(--color-accent);
}
.btn-primary:hover { background: var(--color-accent-dark); border-color: var(--color-accent-dark); }

.btn-danger-ghost {
  background: transparent;
  border-color: var(--color-border);
  color: var(--color-danger);
}
.btn-danger-ghost:hover { background: var(--color-danger-bg); border-color: var(--color-danger); }

