  border-radius: var(--radius-sm);
  background: var(--color-danger-bg);
  border: 1px solid rgba(217, 48, 37, .2);
  font-size: .8125rem;
  color: var(--color-danger);
  display: flex;
  align-items: center;
  gap: .5rem;
}

.dialog-footer {
  display: flex;
  justify-content: flex-end;
  gap: .625rem;
}

